/** Router read responsiveness under an owned external SQLite writer. */
import assert from 'node:assert/strict';import{mkdirSync,writeFileSync}from'node:fs';import{join}from'node:path';import{performance,monitorEventLoopDelay}from'node:perf_hooks';
import{initDatabase,getDb,closeDatabase}from'../../src/db/connection.js';import{createWebSession,revokeUserWebSessions}from'../../src/db/web-sessions.js';import{storeChatMetadata,storeMessage}from'../../src/db/messages.js';
import{WebAuthGateway}from'../../src/channels/web/auth/auth-gateway.js';import{TotpFailureTracker}from'../../src/channels/web/auth/totp-failure-tracker.js';import{WebauthnChallengeTracker}from'../../src/channels/web/auth/webauthn-challenges.js';import{RequestRouterService}from'../../src/channels/web/request-router-service.js';import{getTimelineResponse}from'../../src/channels/web/timeline-service.js';import{assertPathWithinTestFilesystemIsolation}from'../../scripts/test-filesystem-isolation.js';
const workspace=process.env.PICLAW_WORKSPACE!,store=process.env.PICLAW_STORE!;assertPathWithinTestFilesystemIsolation(workspace,process.env,{allowRoot:false});assert.equal(process.env.PICLAW_DB_IN_MEMORY,'0');
mkdirSync(join(workspace,'.piclaw'),{recursive:true});writeFileSync(join(workspace,'.piclaw/config.json'),JSON.stringify({domains:{access:{mode:'single-user'}}}));initDatabase();const db=getDb();storeChatMetadata('web:contention','2026-01-01T00:00:00Z');db.transaction(()=>{for(let n=0;n<100;n++)storeMessage({id:'contention-'+n,chat_jid:'web:contention',sender:'synthetic',sender_name:'Synthetic',content:'synthetic timeline row',timestamp:new Date(1700000000000+n).toISOString(),is_from_me:false,is_bot_message:false})}).immediate();createWebSession('synthetic-writer-cookie','default',3600,'totp');
const json=(v:unknown,s=200)=>Response.json(v,{status:s}),gateway=new WebAuthGateway({accessMode:'single-user',passkeyMode:'',totpSecret:'synthetic-only',internalSecret:'',hasTls:false,sessionTtlSeconds:3600},{json,challenges:new WebauthnChallengeTracker(),failureTracker:new TotpFailureTracker()});
const channel={authGateway:gateway,json,endpointContexts:{auth:()=>({})},clampInt:()=>50,parseOptionalInt:()=>null,handleTimeline:()=>{const r=getTimelineResponse('web:contention',50);return json(r.body,r.status)}}as any;
const router=new RequestRouterService(channel,'single-user'),server=Bun.serve({hostname:'127.0.0.1',port:0,fetch:req=>router.handle(req)});const child=Bun.spawn([process.execPath,'--no-env-file','-e',`import{Database}from'bun:sqlite';const d=new Database(${JSON.stringify(join(store,'messages.db'))});d.exec('BEGIN IMMEDIATE');console.log('LOCKED');await Bun.sleep(500);d.exec('ROLLBACK');d.close()`],{env:{PATH:process.env.PATH,HOME:process.env.HOME},stdout:'pipe',stderr:'pipe'});const timer=setTimeout(()=>child.kill('SIGKILL'),2000),reader=child.stdout.getReader();
try{const first=await reader.read();assert(new TextDecoder().decode(first.value).includes('LOCKED'));const loop=monitorEventLoopDelay({resolution:1});loop.enable();const batches=[];const started=performance.now();let timerMs=0;const tick=new Promise<void>(r=>setTimeout(()=>{timerMs=performance.now()-started;r()},10));for(let n=0;n<20;n++){const at=performance.now();const response=await fetch(new URL('/timeline',server.url),{headers:{cookie:'piclaw_session=synthetic-writer-cookie'}});assert.equal(response.status,200);assert.equal((await response.json()).posts.length,50);batches.push(performance.now()-at);await Bun.sleep(5)}await tick;const readFinishedMs=performance.now()-started;await child.exited;reader.releaseLock();assert.equal(child.exitCode,0);revokeUserWebSessions('default');const denied=await fetch(new URL('/timeline',server.url),{redirect:'manual',headers:{cookie:'piclaw_session=synthetic-writer-cookie'}});assert.equal(denied.status,302);await denied.body?.cancel();await Bun.sleep(10);loop.disable();console.log(JSON.stringify({runtime:Bun.version,writerHoldMs:500,reads:20,batches,readFinishedMs,timerMs,eventLoop:{samples:loop.count,maxMs:loop.max/1e6},revokedDenied:true,busyTimeout:db.query('PRAGMA busy_timeout').get(),scope:'Actual read-only HTTP auth/router/timeline while owned external IMMEDIATE writer holdsWAL; no messagewrites/providers/familytransactions/nativeGC/liveDB. Readsfinishbeforewriterrelease notabsoluteperformanceassertion; boundedchildcleanup.'}));}finally{clearTimeout(timer);if(child.exitCode===null){child.kill('SIGKILL');await child.exited}server.stop(true);closeDatabase()}
